-- Chile milestone translations (ES/DE/FR)

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-sii-pilot-2000s', 'es', 'El SII pilota el DTE con grandes contribuyentes', 'El Servicio de Impuestos Internos de Chile comienza a probar documentos tributarios electrónicos de forma voluntaria con los mayores contribuyentes del país, antes de cualquier mandato general.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-sii-pilot-2000s', 'de', 'SII pilotiert DTE mit Großsteuerpflichtigen', 'Chiles Servicio de Impuestos Internos beginnt, elektronische Steuerdokumente auf freiwilliger Basis mit den größten Steuerpflichtigen des Landes zu testen, vor jedem allgemeinen Mandat.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-sii-pilot-2000s', 'fr', 'Le SII pilote le DTE avec les grands contribuables', 'Le Servicio de Impuestos Internos du Chili commence à tester les documents fiscaux électroniques sur une base volontaire avec les plus grands contribuables du pays, avant tout mandat général.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-established', 'es', 'Documentos Tributarios Electrónicos (DTE) obligatorios para todas las empresas (en vigor desde 2018)', 'Todas las empresas chilenas deben emitir Documentos Tributarios Electrónicos (DTE) — incluyendo facturas (B2B) y boletas (B2C) — validados por el Servicio de Impuestos Internos (SII).', '["Confirme que su sistema de emisión de DTE está autorizado y conectado al SII", "Para ventas superiores a 135 UF, la boleta electrónica debe identificar al comprador por RUT y nombre"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-established', 'de', 'Elektronische Steuerdokumente (DTE) für alle Unternehmen verpflichtend (in Kraft seit 2018)', 'Alle chilenischen Unternehmen müssen Documentos Tributarios Electrónicos (DTE) ausstellen — einschließlich facturas (B2B) und boletas (B2C) —, die vom Servicio de Impuestos Internos (SII) validiert werden.', '["Bestätigen Sie, dass Ihr DTE-Ausstellungssystem autorisiert und mit dem SII verbunden ist", "Bei Verkäufen über 135 UF muss die boleta electrónica den Käufer per RUT und Namen identifizieren"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-established', 'fr', 'Documents fiscaux électroniques (DTE) obligatoires pour toutes les entreprises (en vigueur depuis 2018)', 'Toutes les entreprises chiliennes doivent émettre des Documentos Tributarios Electrónicos (DTE) — y compris les facturas (B2B) et les boletas (B2C) — validés par le Servicio de Impuestos Internos (SII).', '["Confirmez que votre système d''émission de DTE est autorisé et connecté au SII", "Pour les ventes supérieures à 135 UF, la boleta electrónica doit identifier l''acheteur par RUT et nom"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-boleta-2021', 'es', 'Boleta Electrónica obligatoria bajo la Ley 21.210', 'El recibo electrónico de consumidor (usado para transacciones minoristas B2C) se vuelve obligatorio en toda la economía, emitido desde sistemas de punto de venta con certificación del SII.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-boleta-2021', 'de', 'Boleta Electrónica gemäß Ley 21.210 verpflichtend', 'Der elektronische Verbraucherbeleg (für B2C-Einzelhandelstransaktionen verwendet) wird wirtschaftsweit verpflichtend, ausgestellt von Kassensystemen mit SII-Zertifizierung.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-boleta-2021', 'fr', 'Boleta Electrónica obligatoire en vertu de la Ley 21.210', 'Le reçu électronique consommateur (utilisé pour les transactions de détail B2C) devient obligatoire à l''échelle de l''économie, émis depuis des systèmes de point de vente certifiés par le SII.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-digital-delivery', 'es', 'Se requiere entrega digital de la boleta electrónica cuando no se disponga de impresora', 'Las empresas sin capacidad de impresión deben entregar la boleta electrónica digitalmente — por correo electrónico, SMS, WhatsApp, código QR u otro canal electrónico equivalente — en lugar de omitir la entrega por completo.', '["Si carece de impresión en el punto de venta, configure ahora un canal de entrega electrónica (correo electrónico/SMS/QR)", "Las empresas con impresoras generalmente deben seguir entregando la representación impresa"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-digital-delivery', 'de', 'Digitale Zustellung der boleta electrónica erforderlich, wenn kein Drucker verfügbar ist', 'Unternehmen ohne Druckmöglichkeit müssen die boleta electrónica digital zustellen — per E-Mail, SMS, WhatsApp, QR-Code oder einem anderen gleichwertigen elektronischen Kanal — statt die Zustellung ganz auszulassen.', '["Wenn Sie keinen Kassendrucker haben, richten Sie jetzt einen elektronischen Zustellkanal ein (E-Mail/SMS/QR)", "Unternehmen mit Druckern müssen im Allgemeinen weiterhin die gedruckte Darstellung zustellen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cl-digital-delivery', 'fr', 'Livraison numérique de la boleta electrónica requise en l''absence d''imprimante', 'Les entreprises sans capacité d''impression doivent livrer la boleta electrónica numériquement — par e-mail, SMS, WhatsApp, code QR ou un autre canal électronique équivalent — plutôt que d''omettre complètement la livraison.', '["Si vous n''avez pas d''impression au point de vente, mettez en place dès maintenant un canal de livraison électronique (e-mail/SMS/QR)", "Les entreprises disposant d''imprimantes doivent généralement toujours livrer la représentation imprimée"]');
